class Solution {
public:
    int minimumBoxes(int n) {
        int k = 0, sum = 0;
        while (sum + (k + 1) * (k + 2) / 2 <= n) {
            k++;
            sum += k * (k + 1) / 2;
        }

        int res = k * (k + 1) / 2;
        for (int i = 1; sum < n; ++i) {
            sum += i;
            res++;
        }
        return res;
    }
};
